package testkit

import "errors"

var ErrDivideByZero = errors.New("divide by zero")

type Calculator struct{}

func (Calculator) Divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, ErrDivideByZero
	}
	return a / b, nil
}

package testkit_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	testkit "example.com/testkit"
)

func TestCalculatorDivide(t *testing.T) {
	calc := testkit.Calculator{}

	t.Run("divides evenly", func(t *testing.T) {
		got, err := calc.Divide(10, 2)
		require.NoError(t, err)
		assert.Equal(t, 5.0, got)
	})

	t.Run("rejects zero divisor", func(t *testing.T) {
		_, err := calc.Divide(1, 0)
		require.Error(t, err)
		assert.ErrorIs(t, err, testkit.ErrDivideByZero)
	})
}

package testkit

import "errors"

var ErrUserNotFound = errors.New("user not found")

type User struct {
	ID   string
	Name string
}

type UserRepository interface {
	Find(id string) (User, error)
}

type UserService struct {
	repo UserRepository
}

func NewUserService(repo UserRepository) *UserService {
	return &UserService{repo: repo}
}

func (s *UserService) DisplayName(id string) (string, error) {
	user, err := s.repo.Find(id)
	if err != nil {
		return "", err
	}
	return user.Name, nil
}

package testkit_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"

	testkit "example.com/testkit"
)

type mockUserRepository struct {
	mock.Mock
}

func (m *mockUserRepository) Find(id string) (testkit.User, error) {
	args := m.Called(id)
	return args.Get(0).(testkit.User), args.Error(1)
}

func TestUserServiceDisplayName(t *testing.T) {
	t.Run("returns the stored name and records the lookup", func(t *testing.T) {
		repo := new(mockUserRepository)
		repo.On("Find", "u-1").Return(testkit.User{ID: "u-1", Name: "Ada"}, nil)

		svc := testkit.NewUserService(repo)

		name, err := svc.DisplayName("u-1")
		require.NoError(t, err)
		assert.Equal(t, "Ada", name)
		repo.AssertExpectations(t)
		repo.AssertCalled(t, "Find", "u-1")
	})

	t.Run("propagates lookup errors", func(t *testing.T) {
		repo := new(mockUserRepository)
		repo.On("Find", "missing").Return(testkit.User{}, testkit.ErrUserNotFound)

		svc := testkit.NewUserService(repo)

		_, err := svc.DisplayName("missing")
		require.Error(t, err)
		assert.ErrorIs(t, err, testkit.ErrUserNotFound)
		repo.AssertExpectations(t)
	})
}
